namespace tiles_cpp_local { constexpr f64 kPiD = 3.14159265358979323846; }
TileKey tile_at(f64 lon, f64 lat, i32 z) {
  const f64 n = std::ldexp(1.0, z);
  const f64 lr = lat * tiles_cpp_local::kPiD / 180;
  TileKey t;
  t.z = z;
  t.x = static_cast<i32>(converted::fits<int>(std::floor((lon + 180) / 360 * n)));
  t.y = static_cast<i32>(converted::fits<int>(std::floor((1 - std::asinh(std::tan(lr)) / tiles_cpp_local::kPiD) / 2 * n)));
  return t;
}
void CityStream::start(Renderer& renderer, World& world, f64 lon, f64 lat, bool dem) {
  clear();
  r_ = &renderer;
  world_ = &world;
  start_ms_ = ::converted_SpawnCity__main_cpp::now_ms();
  proj_.init(lon, lat);
  terrain_.start(&renderer, &world, proj_, dem);
  origin_tile_ = tile_at(lon, lat);
  offline_ = false;
  real_tiles_ = 0;
  terrain_.corridors_expected = true;
}
void Terrain::disable_dem() {
  dem_ = false;
  if (job_ && converted::present(job_)->id) jobs::cancel(converted::present(job_)->id);
  job_.reset();
  requests_.clear();
  settled_ = true;
}
void training_level(MapFeatures& out) {
  out.procedural = true;
  auto road = [&](f32 x, f32 y, f32 w, f32 h, RoadClass c) {
    // the plane's long side is the centreline (these match trainingRoutes())
    MapFeatures::Road r;
    r.cls = c;
    if (w >= h) r.points = {{x - w / 2, y}, {x + w / 2, y}};
    else r.points = {{x, y - h / 2}, {x, y + h / 2}};
    out.roads.push_back(std::move(r));
  };
  road(0, -38, 124, 8, RoadClass::secondary);
  road(0, 38, 124, 8, RoadClass::secondary);
  road(-62, 0, 8, 76, RoadClass::secondary);
  road(62, 0, 8, 76, RoadClass::secondary);
  road(0, 0, 168, 11, RoadClass::primary);
  road(0, 0, 10, 152, RoadClass::primary);
  road(0, 54, 140, 8, RoadClass::tertiary);
  {
    // the pedestrian bridge over the pond (5 x 42 m)
    MapFeatures::Road b;
    b.cls = RoadClass::pedestrian;
    b.bridge = true;
    b.points = {{34, converted::minus(31, 21)}, {34, converted::plus(31, 21)}};
    out.roads.push_back(std::move(b));
  }
  auto rect = [](f32 x, f32 y, f32 w, f32 h) { return std::vector<Vec2>{{x - w / 2, y - h / 2}, {x + w / 2, y - h / 2}, {x + w / 2, y + h / 2}, {x - w / 2, y + h / 2}}; };
  for (const auto& [x, y, w, h] : std::initializer_list<std::array<f32, 4>>{{-38, 28, 42, 30}, {48, -25, 32, 22}}) {
    MapFeatures::Area a;
    a.kind = AreaKind::park;
    a.rings.push_back(rect(x, y, w, h));
    out.areas.push_back(std::move(a));
  }
  {
    // the saturated harbour pond: a circle of 20 m stretched 1.55 x .92 at (34, 31)
    MapFeatures::Area pond;
    pond.kind = AreaKind::water;
    std::vector<Vec2> ring;
    for (int i = 0; i < 48; converted::pre_inc(i)) {
      const f32 a = 2 * kPi * static_cast<f32>(i) / 48;
      ring.push_back({34 + std::cos(a) * 20 * 1.55f, 31 + std::sin(a) * 20 * 0.92f});
    }
    pond.rings.push_back(std::move(ring));
    out.areas.push_back(std::move(pond));
  }
  // the compact skyline: x, y, width, depth, height
  const std::array<f32, 5> houses[] = {{-47, -22, 15, 13, 10}, {-27, -23, 13, 12, 15}, {31, -23, 15, 13, 12}, {50, -22, 12, 12, 18}, {-51, 18, 13, 12, 14},
                                       {-18, 24, 14, 11, 20},  {54, 15, 13, 12, 11},   {-55, 61, 16, 11, 9},  {55, 64, 18, 12, 13}};
  u32 n = 0;
  for (const auto& [x, y, w, d, h] : houses) {
    MapFeatures::Building b;
    b.rings.push_back(rect(x, y, w, d));
    b.base = 0;
    b.top = h;
    b.seed = 0x7a1e0u + n++ * 2654435761u;
    out.buildings.push_back(std::move(b));
  }
}
void procedural_city(f64 cx, f64 cy, f64 size, u32 seed, MapFeatures& out) {
  // A walled-town grid with a market square: blocks of narrow terraced houses (3-6 storeys),
  // a ring road, a park and a lake shore to the north. Nothing here comes from real map data.
  Rng rng = Rng::seeded(seed);
  out.procedural = true;
  const f32 pitch = 76, street = 12;
  const int blocks = std::max(3, static_cast<int>(converted::fits<int>(size / pitch)));
  const f32 half = blocks * pitch * 0.5f;
  const f32 x0 = static_cast<f32>(cx) - half, y0 = static_cast<f32>(cy) - half;
  for (int i = 0; i <= blocks; converted::pre_inc(i)) {
    const f32 t = -half + i * pitch;
    MapFeatures::Road a, b;
    const bool ring = i == 0 || i == blocks;
    a.cls = b.cls = ring ? RoadClass::secondary : (i == blocks / 2 ? RoadClass::tertiary : RoadClass::minor);
    a.points = {{static_cast<f32>(cx) + t, static_cast<f32>(cy) - half}, {static_cast<f32>(cx) + t, static_cast<f32>(cy) + half}};
    b.points = {{static_cast<f32>(cx) - half, static_cast<f32>(cy) + t}, {static_cast<f32>(cx) + half, static_cast<f32>(cy) + t}};
    out.roads.push_back(a);
    out.roads.push_back(b);
  }
  for (int bx = 0; bx < blocks; converted::pre_inc(bx))
    for (int by = 0; by < blocks; converted::pre_inc(by)) {
      const f32 a0 = x0 + bx * pitch + street * 0.5f + 2, b0 = y0 + by * pitch + street * 0.5f + 2;
      const f32 inner = pitch - street - 4;
      const bool market = bx == blocks / 2 && by == blocks / 2;
      const bool park = (bx == 1 && by == converted::minus(blocks, 2));
      if (market || park) {
        MapFeatures::Area a;
        a.kind = market ? AreaKind::sand : AreaKind::park;
        a.rings.push_back({{a0, b0}, {a0 + inner, b0}, {a0 + inner, b0 + inner}, {a0, b0 + inner}});
        out.areas.push_back(a);
        continue;
      }
      // Terraced houses along the four sides of the block, a courtyard in the middle.
      const f32 depth = rng.range(10, 14);
      for (int side = 0; side < 4; converted::pre_inc(side)) {
        f32 along = 0;
        while (along < inner - 4) {
          const f32 w = std::fmin(rng.range(7, 13), inner - along);
          f32 ax, ay, bx2, by2;
          switch (side) {
            case 0: ax = a0 + along; ay = b0; bx2 = ax + w; by2 = b0 + depth; break;
            case 1: ax = a0 + inner - depth; ay = b0 + along; bx2 = a0 + inner; by2 = ay + w; break;
            case 2: ax = a0 + inner - along - w; ay = b0 + inner - depth; bx2 = ax + w; by2 = b0 + inner; break;
            default: ax = a0; ay = b0 + inner - along - w; bx2 = a0 + depth; by2 = ay + w; break;
          }
          // Skip the corner overlaps of side 1..3 with side 0 / 2.
          if ((side == 1 || side == 3) && (ay < b0 + depth || by2 > b0 + inner - depth)) { along += w; continue; }
          MapFeatures::Building b;
          b.rings.push_back({{ax, ay}, {bx2, ay}, {bx2, by2}, {ax, by2}});
          b.top = 3.2f * static_cast<f32>(converted::plus(3, static_cast<int>(converted::fits<int>(rng.unit() * 4)))) + rng.range(0, 1.5f);
          b.seed = rng.next();
          out.buildings.push_back(std::move(b));
          along += w;
        }
      }
    }
  // Lake shore to the north (a stand-in for the Bodensee).
  MapFeatures::Area lake;
  lake.kind = AreaKind::water;
  const f32 ly = static_cast<f32>(cy) + half + 30;
  lake.rings.push_back({{static_cast<f32>(cx) - half * 2, ly}, {static_cast<f32>(cx) + half * 2, ly}, {static_cast<f32>(cx) + half * 2, ly + 900},
                        {static_cast<f32>(cx) - half * 2, ly + 900}});
  out.areas.push_back(lake);
}
f32 road_width(RoadClass c) {
  switch (c) {
    case RoadClass::motorway: return 14;
    case RoadClass::trunk: return 12;
    case RoadClass::primary: return 11;
    case RoadClass::secondary: return 9;
    case RoadClass::tertiary: return 8;
    case RoadClass::minor: return 6.5f;
    case RoadClass::service: return 4.2f;
    case RoadClass::track: return 3;
    case RoadClass::path: return 2.2f;
    case RoadClass::pedestrian: return 3.6f;
    case RoadClass::river: return 18;
    case RoadClass::canal: return 12;
    case RoadClass::stream: return 4.5f;
  }
  return 6;
}
bool road_is_water(RoadClass c) { return c == RoadClass::river || c == RoadClass::canal || c == RoadClass::stream; }
bool road_drivable(RoadClass c) { return static_cast<u8>(c) <= static_cast<u8>(RoadClass::service); }
namespace tiles_cpp_local { struct FurnishIndex {
  static constexpr f32 kCell = 20;
  struct Seg { Vec2 a, b; f32 half; u32 road; bool paved; };
  /// A house's outline: the outer ring of the tile's building `index`, or the apron's ring `index`
  /// (the outlines that reach over the tile's edge), with its bounding box.
  struct Ring { bool apron; u32 index; Vec4 box; };
  std::vector<Seg> segs;
  std::vector<Ring> rings;
  kern::Map<u64, std::vector<u32>> seg_cells, ring_cells;
  static u64 key(i32 x, i32 y) { return (static_cast<u64>(static_cast<u32>(x)) << 32) | static_cast<u32>(y); }
  static i32 cell(f32 v) { return static_cast<i32>(converted::fits<int>(std::floor(v / kCell))); }
  void add_seg(Vec2 a, Vec2 b, f32 half, u32 road, bool paved) {
    const u32 id = static_cast<u32>(segs.size());
    segs.push_back({a, b, half, road, paved});
    const f32 m = half + 3;
    for (i32 x = cell(std::fmin(a.x, b.x) - m); x <= cell(std::fmax(a.x, b.x) + m); converted::pre_inc(x))
      for (i32 y = cell(std::fmin(a.y, b.y) - m); y <= cell(std::fmax(a.y, b.y) + m); converted::pre_inc(y)) seg_cells[key(x, y)].push_back(id);
  }
  void add_ring(const std::vector<Vec2>& r, bool apron, u32 index) {
    if (r.size() < 3) return;
    Vec4 box{1e30f, 1e30f, -1e30f, -1e30f};
    for (Vec2 p : r) box = {std::fmin(box.x, p.x), std::fmin(box.y, p.y), std::fmax(box.z, p.x), std::fmax(box.w, p.y)};
    if (box.z - box.x > 4000 || box.w - box.y > 4000) return;
    const u32 id = static_cast<u32>(rings.size());
    rings.push_back({apron, index, box});
    for (i32 x = cell(box.x); x <= cell(box.z); converted::pre_inc(x))
      for (i32 y = cell(box.y); y <= cell(box.w); converted::pre_inc(y)) ring_cells[key(x, y)].push_back(id);
  }
  /// Inside a house (of the tile's `buildings` or the `apron` the rings were added from).
  bool built(Vec2 p, const std::vector<MapFeatures::Building>& buildings, const std::vector<std::vector<Vec2>>& apron) const {
    const auto it = ring_cells.find(key(cell(p.x), cell(p.y)));
    if (it == ring_cells.end()) return false;
    for (u32 id : it->second) {
      const Ring& g = converted::at(rings, id);
      if (p.x < g.box.x || p.x > g.box.z || p.y < g.box.y || p.y > g.box.w) continue;
      const std::vector<Vec2>& r = g.apron ? converted::at(apron, g.index) : converted::at(converted::at(buildings, g.index).rings, 0);
      bool c = false;
      for (std::size_t i = 0, j = r.size() - 1; i < r.size(); j = converted::post_inc(i))
        if ((converted::at(r, i).y > p.y) != (converted::at(r, j).y > p.y) && p.x < (converted::at(r, j).x - converted::at(r, i).x) * (p.y - converted::at(r, i).y) / (converted::at(r, j).y - converted::at(r, i).y + 1e-12f) + converted::at(r, i).x) c = !c;
      if (c) return true;
    }
    return false;
  }
  /// Clear of every street by `paved` beyond its carriageway and of every path by `unpaved`.
  bool off_roads(Vec2 p, f32 paved, f32 unpaved) const {
    const auto it = seg_cells.find(key(cell(p.x), cell(p.y)));
    if (it == seg_cells.end()) return true;
    for (u32 id : it->second) {
      const Seg& s = converted::at(segs, id);
      const Vec2 d = s.b - s.a;
      const f32 l2 = d.x * d.x + d.y * d.y;
      const f32 t = l2 > 1e-6f ? clampf(((p.x - s.a.x) * d.x + (p.y - s.a.y) * d.y) / l2, 0, 1) : 0;
      if (std::hypot(p.x - s.a.x - d.x * t, p.y - s.a.y - d.y * t) < s.half + (s.paved ? paved : unpaved)) return false;
    }
    return true;
  }
}; }
void furnish(MapFeatures& out, const Vec4& sq, const std::vector<std::vector<Vec2>>& apron) { using tiles_cpp_local::FurnishIndex;
  out.trees.clear();
  out.lamps.clear();
  FurnishIndex ix;
  for (u32 ri = 0; ri < out.roads.size(); ++ri) {
    const MapFeatures::Road& r = converted::at(out.roads, ri);
    if (road_is_water(r.cls)) continue;
    const bool paved = r.cls != RoadClass::path && r.cls != RoadClass::track;
    for (std::size_t k = 0; k + 1 < r.points.size(); converted::pre_inc(k)) ix.add_seg(converted::at(r.points, k), converted::at(r.points, k + 1), road_width(r.cls) / 2, ri, paved);
  }
  for (u32 bi = 0; bi < out.buildings.size(); ++bi)
    if (!converted::at(out.buildings, bi).rings.empty()) ix.add_ring(converted::at(converted::at(out.buildings, bi).rings, 0), false, bi);
  for (u32 ai = 0; ai < apron.size(); ++ai) ix.add_ring(converted::at(apron, ai), true, ai);
  auto inside = [&](Vec2 p) { return p.x >= sq.x && p.x < sq.z && p.y >= sq.y && p.y < sq.w; };
  constexpr f32 kPi2 = 6.2831853f;
  kern::Set<u64> lamp_cells;
  for (u32 ri = 0; ri < out.roads.size(); ++ri) {
    const MapFeatures::Road& r = converted::at(out.roads, ri);
    if (road_is_water(r.cls) || r.points.size() < 2) continue;
    const f32 w = road_width(r.cls);
    // ---- trees beside the streets cars drive (world_liveliness.mjs: trunk 2.3 m, crown 0.92 m,
    // 2.4 m clear of houses): every 37 m, alternating sides, beyond the pavement
    if (road_drivable(r.cls) && !r.bridge && w <= 14) {
      f32 carry = 17;
      u32 i = ri * 7;
      for (std::size_t k = 0; k + 1 < r.points.size(); converted::pre_inc(k)) {
        const Vec2 a = converted::at(r.points, k), d = converted::at(r.points, k + 1) - a;
        const f32 len = std::hypot(d.x, d.y);
        if (len < 1) continue;
        const Vec2 u = d * (1 / len), right{u.y, -u.x};
        for (f32 t = carry; t < len; t += 37, ++i) {
          const f32 side = (i & 1) ? 1.0f : -1.0f, off = w * 0.5f + 2.2f + static_cast<f32>(i % 4) * 0.4f;
          const Vec2 c = a + u * t + right * (side * off);
          if (!inside(c) || !ix.off_roads(c, 1.9f, 0.6f) || ix.built(c, out.buildings, apron)) continue;
          bool free = true;
          for (int j = 0; j < 6 && free; converted::pre_inc(j)) free = !ix.built(c + Vec2{std::cos(static_cast<f32>(j) * kPi2 / 6), std::sin(static_cast<f32>(j) * kPi2 / 6)} * 2.4f, out.buildings, apron);
          if (free) out.trees.push_back({c, 0.82f + static_cast<f32>(i % 5) * 0.045f});
        }
        carry = std::fmod(carry + 37 - std::fmod(len, 37.0f), 37.0f);
      }
    }
    // ---- street lamps (street_lamps.mjs setLampRoads): every street but paths and tracks
    if (r.cls != RoadClass::path && r.cls != RoadClass::track) {
      f32 carry = 34 * 0.5f, side = 1;
      for (std::size_t k = 0; k + 1 < r.points.size(); converted::pre_inc(k)) {
        const Vec2 a = converted::at(r.points, k), d = converted::at(r.points, k + 1) - a;
        const f32 len = std::hypot(d.x, d.y);
        if (len < 0.5f) continue;
        const Vec2 u = d * (1 / len), n{-u.y, u.x};
        for (f32 t = carry; t < len; t += 34) {
          side = -side;
          const Vec2 c = a + u * t + n * ((w / 2 + 1.15f) * side);
          if (!inside(c)) continue;
          const u64 cell = (static_cast<u64>(static_cast<u32>(std::lround(c.x / 8))) << 32) | static_cast<u32>(std::lround(c.y / 8));
          // on its kerb: off every other street's carriageway, not in a house (nor its arm's foot)
          if (!ix.off_roads(c, 0.35f, 0.3f) || ix.built(c, out.buildings, apron)) continue;
          if (!lamp_cells.insert(cell).second) continue;
          out.lamps.push_back({c, std::atan2(-n.y * side, -n.x * side)});
        }
        carry = std::fmod(std::fmod(carry - len, 34.0f) + 34.0f, 34.0f);
      }
    }
  }
}
namespace terrain_cpp_local { Vec4 interior_of(f32 x0, f32 y0, f32 span, f32 margin) { return {x0 + margin, y0 + margin, x0 + span - margin, y0 + span - margin}; } }
Vec4 Terrain::interior(const Grid& g) const {
  return terrain_cpp_local::interior_of(g.x0, g.y0, g.step * static_cast<f32>(g.n > 0 ? g.n - 1 : 0), kDemMargin);
}
f32 Terrain::grid_at(const Grid& g, f32 x, f32 y) const {
  if (g.n < 2) return 0;
  const f32 lim = static_cast<f32>(g.n) - 1.001f;
  const f32 fx = clampf((x - g.x0) / g.step, 0, lim), fy = clampf((y - g.y0) / g.step, 0, lim);
  const u32 i = static_cast<u32>(converted::fits<unsigned int>(fx)), j = static_cast<u32>(converted::fits<unsigned int>(fy));
  const f32 tx = fx - i, ty = fy - j;
  const std::size_t at = static_cast<std::size_t>(j) * g.n + i;
  return (converted::at(g.h, at) * (1 - tx) + converted::at(g.h, at + 1) * tx) * (1 - ty) + (converted::at(g.h, at + g.n) * (1 - tx) + converted::at(g.h, at + g.n + 1) * tx) * ty;
}
f32 Terrain::elevation(f32 x, f32 y) const {
  if (!grid_ready_) return 0.0f;
  // the window that knows the place (its interior); else any that holds it; else the player's,
  // held at its edge (far ground nobody stands on: the horizon)
  auto in = [&](const Vec4& r) { return x >= r.x && y >= r.y && x <= r.z && y <= r.w; };
  if (side_.empty() || in(interior(grid_))) return grid_at(grid_, x, y) - ref_height_;
  for (const Grid& g : side_) if (in(interior(g))) return grid_at(g, x, y) - ref_height_;
  if (in(terrain_cpp_local::interior_of(grid_.x0, grid_.y0, grid_.step * static_cast<f32>(grid_.n - 1), 0))) return grid_at(grid_, x, y) - ref_height_;
  for (const Grid& g : side_) if (in(terrain_cpp_local::interior_of(g.x0, g.y0, g.step * static_cast<f32>(g.n - 1), 0))) return grid_at(g, x, y) - ref_height_;
  return grid_at(grid_, x, y) - ref_height_;
}
namespace terrain_cpp_local { constexpr f32 kRoadGrid = 24, kRoadBlend = 4.5f; }
namespace terrain_cpp_local { u64 road_key(i32 ix, i32 iy) { return (static_cast<u64>(static_cast<u32>(ix)) << 32) | static_cast<u32>(iy); } }
f32 Terrain::road_field(f32 x, f32 y) const {
  // terrain_craters.mjs roadField: the ground smoothed over ~36 m (tent kernel) - a street's
  // profile along its length; one field for all streets, so crossing streets agree at a junction
  f32 sum = 0, wsum = 0;
  for (int j = -2; j <= 2; converted::pre_inc(j))
    for (int i = -2; i <= 2; converted::pre_inc(i)) {
      const f32 w = static_cast<f32>(converted::times((converted::minus(3, std::abs(i))), (converted::minus(3, std::abs(j)))));
      sum += elevation(x + static_cast<f32>(i) * 9, y + static_cast<f32>(j) * 9) * w;
      wsum += w;
    }
  return sum / wsum;
}
void Terrain::set_corridors(u64 owner, const Vec4& bounds, const std::vector<MapFeatures::Road>& roads, const std::vector<f32>& widths) {
  remove_corridors(owner);
  auto set = std::make_unique<CorridorSet>();
  converted::present(set)->owner = owner;
  converted::present(set)->bounds = bounds;
  converted::present(set)->box = {1e30f, 1e30f, -1e30f, -1e30f};
  std::vector<Vec2> pts;
  std::vector<f32> hs;
  for (std::size_t s = 0; s < roads.size(); converted::pre_inc(s)) {
    const std::vector<Vec2>& points = converted::at(roads, s).points;
    const f32 width = converted::at(widths, s);
    if (points.size() < 2 || !(width > 0)) continue;
    // the centre line every 5 m, its heights from the smooth field
    pts.clear();
    for (std::size_t i = 0; i + 1 < points.size(); converted::pre_inc(i)) {
      const Vec2 a = converted::at(points, i), b = converted::at(points, i + 1);
      const i32 k = std::max(1, static_cast<i32>(converted::fits<int>(std::ceil(std::hypot(b.x - a.x, b.y - a.y) / 5))));
      for (i32 q = 0; q < k; converted::pre_inc(q)) pts.push_back(a + (b - a) * (static_cast<f32>(q) / static_cast<f32>(k)));
    }
    pts.push_back(converted::back(points));
    hs.resize(converted::count(pts.size()));
    const f32 half = width / 2, reach = half + terrain_cpp_local::kRoadBlend;
    // (only what can reach into the tile's own square)
    auto near = [&](Vec2 p) { return p.x > bounds.x - reach - 6 && p.x < bounds.z + reach + 6 && p.y > bounds.y - reach - 6 && p.y < bounds.w + reach + 6; };
    for (std::size_t i = 0; i < pts.size(); converted::pre_inc(i)) converted::at(hs, i) = near(converted::at(pts, i)) ? road_field(converted::at(pts, i).x, converted::at(pts, i).y) : 0;
    for (std::size_t i = 0; i + 1 < pts.size(); converted::pre_inc(i)) {
      const Vec2 a = converted::at(pts, i), b = converted::at(pts, i + 1);
      if (!near(a) || !near(b)) continue;
      const f32 dx = b.x - a.x, dy = b.y - a.y, l2 = dx * dx + dy * dy;
      if (l2 < 1e-4f) continue;
      const CorridorSeg seg{a.x, a.y, dx, dy, l2, converted::at(hs, i), converted::at(hs, i + 1), half};
      const f32 x0 = std::fmin(a.x, b.x) - reach, x1 = std::fmax(a.x, b.x) + reach, y0 = std::fmin(a.y, b.y) - reach, y1 = std::fmax(a.y, b.y) + reach;
      converted::present(set)->box = {std::fmin(converted::present(set)->box.x, x0), std::fmin(converted::present(set)->box.y, y0), std::fmax(converted::present(set)->box.z, x1), std::fmax(converted::present(set)->box.w, y1)};
      for (i32 gx = static_cast<i32>(converted::fits<int>(std::floor(x0 / terrain_cpp_local::kRoadGrid))); gx <= static_cast<i32>(converted::fits<int>(std::floor(x1 / terrain_cpp_local::kRoadGrid))); converted::pre_inc(gx))
        for (i32 gy = static_cast<i32>(converted::fits<int>(std::floor(y0 / terrain_cpp_local::kRoadGrid))); gy <= static_cast<i32>(converted::fits<int>(std::floor(y1 / terrain_cpp_local::kRoadGrid))); converted::pre_inc(gy)) converted::present(set)->grid[terrain_cpp_local::road_key(gx, gy)].push_back(seg);
    }
  }
  const Vec4 box = converted::present(set)->box;
  corridors_.push_back(std::move(set));
  // the ground of the tile's square changed where its streets run (nobody else's ground did)
  if (box.z > box.x) {
    const Vec4 c{std::fmax(box.x, bounds.x), std::fmax(box.y, bounds.y), std::fmin(box.z, bounds.z), std::fmin(box.w, bounds.w)};
    if (c.z > c.x && c.w > c.y) dirty(c.x, c.y, c.z, c.w, false);
  }
}
i32 Terrain::corridor_set(f32 x, f32 y) const {
  // the map tile whose square holds the point (the squares tile the plane: west / south edge in - one at most)
  for (std::size_t i = 0; i < corridors_.size(); converted::pre_inc(i)) {
    const CorridorSet& s = *converted::present(converted::at(corridors_, i));
    if (x >= s.bounds.x && x < s.bounds.z && y >= s.bounds.y && y < s.bounds.w) return static_cast<i32>(i);
  }
  return -1;
}
f32 Terrain::road_level(f32 x, f32 y, f32 h) const {
  // terrain_craters.mjs roadLevel: every corridor covering the point contributes (weighted), so
  // junctions blend smoothly, no steps
  const i32 at = corridors_.empty() ? -1 : corridor_set(x, y);
  if (at < 0) return h;
  const CorridorSet& set = *converted::present(converted::at(corridors_, static_cast<std::size_t>(at)));
  const auto it = set.grid.find(terrain_cpp_local::road_key(static_cast<i32>(converted::fits<int>(std::floor(x / terrain_cpp_local::kRoadGrid))), static_cast<i32>(converted::fits<int>(std::floor(y / terrain_cpp_local::kRoadGrid)))));
  if (it == set.grid.end()) return h;
  f32 best = 0, sw = 0, sh = 0;
  for (const CorridorSeg& s : it->second) {
    const f32 t = clampf(((x - s.ax) * s.dx + (y - s.ay) * s.dy) / s.l2, 0, 1);
    const f32 px = s.ax + s.dx * t, py = s.ay + s.dy * t, d = std::hypot(x - px, y - py);
    const f32 w = d <= s.half ? 1 : d >= s.half + terrain_cpp_local::kRoadBlend ? 0 : 1 - (d - s.half) / terrain_cpp_local::kRoadBlend;
    if (w <= 0) continue;
    const f32 ws = w * w * (3 - 2 * w);
    sw += ws;
    sh += ws * (s.ha + (s.hb - s.ha) * t);
    best = std::fmax(best, w);
  }
  if (sw <= 0) return h;
  return h + (sh / sw - h) * (best * best * (3 - 2 * best));
}
f32 Terrain::footprint_base(const std::vector<Vec2>& ring) const {
  if (!grid_ready_ && craters_.empty()) return 0;
  f32 m = 1e9f;
  for (std::size_t i = 0; i < ring.size(); converted::pre_inc(i)) {
    const Vec2 a = converted::at(ring, i), b = converted::at(ring, converted::rem((i + 1), ring.size()));
    // (the natural ground, or the street's corridor where it cuts lower: never floating)
    const Vec2 c = (a + b) * 0.5f;
    const f32 ea = elevation(a.x, a.y), ec = elevation(c.x, c.y);
    m = std::fmin(m, std::fmin(std::fmin(ea, road_level(a.x, a.y, ea)), std::fmin(ec, road_level(c.x, c.y, ec))));
  }
  return m < 1e8f ? m : 0.0f;
}
std::vector<std::vector<Vec2>> clip_line(const std::vector<Vec2>& line, const Vec4& rect) {
  // Liang-Barsky per stretch; stretches that follow each other inside stay one part
  std::vector<std::vector<Vec2>> out;
  std::vector<Vec2> cur;
  auto close = [&] { if (cur.size() >= 2) out.push_back(std::move(cur)); cur.clear(); };
  for (std::size_t i = 0; i + 1 < line.size(); converted::pre_inc(i)) {
    const Vec2 a = converted::at(line, i), b = converted::at(line, i + 1);
    const f32 dx = b.x - a.x, dy = b.y - a.y;
    f32 t0 = 0, t1 = 1;
    bool in = true;
    const f32 p[4] = {-dx, dx, -dy, dy}, q[4] = {a.x - rect.x, rect.z - a.x, a.y - rect.y, rect.w - a.y};
    for (int k = 0; k < 4 && in; converted::pre_inc(k)) {
      if (converted::at(p, k) == 0) { in = converted::at(q, k) >= 0; continue; }
      const f32 r = converted::at(q, k) / converted::at(p, k);
      if (converted::at(p, k) < 0) { if (r > t1) in = false; else if (r > t0) t0 = r; }
      else { if (r < t0) in = false; else if (r < t1) t1 = r; }
    }
    if (!in || t1 <= t0) { close(); continue; }
    const Vec2 ca{a.x + dx * t0, a.y + dy * t0}, cb{a.x + dx * t1, a.y + dy * t1};
    if (cur.empty()) cur.push_back(ca);
    else if (t0 > 0) { close(); cur.push_back(ca); }  // (it came back in: a new part)
    cur.push_back(cb);
    if (t1 < 1) close();
  }
  close();
  return out;
}
namespace terrain_cpp_local { u64 key2(i32 i, i32 j) { return (static_cast<u64>(static_cast<u32>(i)) << 32) | static_cast<u32>(j); } }
f32 crater_profile(f32 r, f32 radius, f32 depth, f32 rim) {
  const f32 bowl = radius * 0.5f;
  if (r < bowl) return -depth * (1 - (r / bowl) * (r / bowl));
  if (r >= radius) return 0;
  const f32 x = (r - bowl) / (radius - bowl), k = (x - 0.12f) / 0.14f;
  return rim * std::exp(-(k * k)) * (1 - x);
}
f32 Terrain::node_height(f32 x, f32 y) const {
  const f32 e = elevation(x, y);
  f32 h = road_level(x, y, e);
  for (const Crater& c : craters_) {
    const f32 dx = x - c.c.x, dy = y - c.c.y;
    if (std::fabs(dx) >= c.r || std::fabs(dy) >= c.r) continue;
    const f32 r = std::sqrt(dx * dx + dy * dy);
    if (r < c.r) h += crater_profile(r, c.r, c.depth, c.rim);
  }
  if (!water_.empty() && water_at(x, y)) return std::fmin(h, e - kWaterBed);
  return h;
}
f32 Terrain::height(f32 x, f32 y) const {
  // terrain_surface.mjs triangleHeightAt: the SW-NE diagonal of every 5 m cell.
  const f32 x0 = std::floor(x / kStep) * kStep, y0 = std::floor(y / kStep) * kStep;
  const f32 u = (x - x0) / kStep, v = (y - y0) / kStep;
  const f32 a = node_height(x0, y0), d = node_height(x0 + kStep, y0 + kStep);
  return u >= v ? a + (node_height(x0 + kStep, y0) - a) * (u - v) + (d - a) * v : a + (node_height(x0, y0 + kStep) - a) * (v - u) + (d - a) * u;
}
HeightSampler Terrain::sampler(f32 offset) const {
  (void)offset;
  HeightSampler s;
  s.user = const_cast<Terrain*>(this);
  s.fn = [](void* u, f64 x, f64 y) -> f64 { return static_cast<const Terrain*>(u)->height(static_cast<f32>(x), static_cast<f32>(y)); };
  return s;
}
bool Terrain::water_cell(i32 cx, i32 cy) const {
  // the 256 bits of the cell's 64 m block
  auto it = water_.find(terrain_cpp_local::key2(cx >> 4, cy >> 4));
  if (it == water_.end()) return false;
  const u32 idx = static_cast<u32>(converted::plus(converted::times((cy & 15), 16), (cx & 15)));
  return (converted::at(it->second.bits, idx >> 6) >> (idx & 63)) & 1u;
}
bool Terrain::on_bridge(f32 x, f32 y) const {
  for (const Bridge& b : bridges_) {
    const f32 dx = x - b.c.x, dy = y - b.c.y;
    if (std::fabs(dx) > b.hl + b.hw || std::fabs(dy) > b.hl + b.hw) continue;
    const f32 c = std::cos(b.yaw), s = std::sin(b.yaw), u = dx * c + dy * s, v = -dx * s + dy * c;
    if (std::fabs(u) <= b.hl && std::fabs(v) <= b.hw) return true;
  }
  return false;
}
bool Terrain::water_at(f32 x, f32 y) const {
  if (water_.empty()) return false;
  if (!water_cell(static_cast<i32>(converted::fits<int>(std::floor(x / kWaterCell))), static_cast<i32>(converted::fits<int>(std::floor(y / kWaterCell))))) return false;
  return bridges_.empty() || !on_bridge(x, y);
}
void Terrain::set_water_cell(i32 cx, i32 cy) {
  WaterBlock& b = water_[terrain_cpp_local::key2(cx >> 4, cy >> 4)];
  const u32 idx = static_cast<u32>(converted::plus(converted::times((cy & 15), 16), (cx & 15)));
  if (!((converted::at(b.bits, idx >> 6) >> (idx & 63)) & 1u)) ++stats_.water_cells;
  converted::at(b.bits, idx >> 6) |= u64{1} << (idx & 63);
}
void Terrain::add_water_polygon(const std::vector<std::vector<Vec2>>& rings) {
  if (rings.empty() || converted::at(rings, 0).size() < 3) return;
  f32 y_lo = 1e9f, y_hi = -1e9f, x_lo = 1e9f, x_hi = -1e9f;
  for (Vec2 p : converted::at(rings, 0)) { y_lo = std::fmin(y_lo, p.y); y_hi = std::fmax(y_hi, p.y); x_lo = std::fmin(x_lo, p.x); x_hi = std::fmax(x_hi, p.x); }
  // Scanline fill (even-odd over all rings: courtyards / islands stay dry), cell centres.
  std::vector<f32> xs;
  const i32 j0 = static_cast<i32>(converted::fits<int>(std::floor(y_lo / kWaterCell))), j1 = static_cast<i32>(converted::fits<int>(std::floor(y_hi / kWaterCell)));
  for (i32 j = j0; j <= j1; converted::pre_inc(j)) {
    const f32 y = (static_cast<f32>(j) + 0.5f) * kWaterCell;
    xs.clear();
    for (const auto& ring : rings)
      for (std::size_t a = 0, c = ring.size() - 1; a < ring.size(); c = converted::post_inc(a)) {
        const f32 ya = converted::at(ring, a).y, yc = converted::at(ring, c).y;
        if ((ya > y) != (yc > y)) xs.push_back(converted::at(ring, a).x + (y - ya) / (yc - ya) * (converted::at(ring, c).x - converted::at(ring, a).x));
      }
    std::stable_sort(xs.begin(), xs.end());
    for (std::size_t k = 0; k + 1 < xs.size(); k += 2) {
      const i32 ia = static_cast<i32>(converted::fits<int>(std::ceil(converted::at(xs, k) / kWaterCell - 0.5f))), ib = static_cast<i32>(converted::fits<int>(std::floor(converted::at(xs, k + 1) / kWaterCell - 0.5f)));
      for (i32 i = ia; i <= ib; converted::pre_inc(i)) set_water_cell(i, j);
    }
  }
  dirty(x_lo, y_lo, x_hi, y_hi);
}
namespace terrain_cpp_local { f32 srgb_to_linear(f32 v) { return v <= 0.04045f ? v / 12.92f : std::pow((v + 0.055f) / 1.055f, 2.4f); } }
namespace terrain_cpp_local { Vec3 to_linear(Vec3 c) { return {srgb_to_linear(c.x), srgb_to_linear(c.y), srgb_to_linear(c.z)}; } }
void Terrain::add_tint(u64 owner, const std::vector<std::vector<Vec2>>& rings, Vec3 srgb) {
  if (rings.empty() || converted::at(rings, 0).size() < 3) return;
  Tint t{owner, {1e30f, 1e30f, -1e30f, -1e30f}, terrain_cpp_local::to_linear(srgb), rings};
  for (Vec2 p : converted::at(rings, 0)) {
    t.box.x = std::fmin(t.box.x, p.x); t.box.y = std::fmin(t.box.y, p.y);
    t.box.z = std::fmax(t.box.z, p.x); t.box.w = std::fmax(t.box.w, p.y);
  }
  repaint(t.box);
  tints_.push_back(std::move(t));
}
void Terrain::add_waterway(const std::vector<Vec2>& pts, f32 width, f32 speed) {
  f32 x_lo = 1e9f, y_lo = 1e9f, x_hi = -1e9f, y_hi = -1e9f;
  for (std::size_t k = 0; k + 1 < pts.size(); converted::pre_inc(k)) {
    const Vec2 a = converted::at(pts, k), c = converted::at(pts, k + 1);
    const f32 l = std::hypot(c.x - a.x, c.y - a.y);
    if (l < 0.2f) continue;
    const Vec2 u{(c.x - a.x) / l, (c.y - a.y) / l};
    const f32 half = width / 2, reach = half + 30;  // world_water.mjs: flow felt 30 m beyond the banks
    const i32 i0 = static_cast<i32>(converted::fits<int>(std::floor((std::fmin(a.x, c.x) - reach) / kWaterCell))), i1 = static_cast<i32>(converted::fits<int>(std::floor((std::fmax(a.x, c.x) + reach) / kWaterCell)));
    const i32 j0 = static_cast<i32>(converted::fits<int>(std::floor((std::fmin(a.y, c.y) - reach) / kWaterCell))), j1 = static_cast<i32>(converted::fits<int>(std::floor((std::fmax(a.y, c.y) + reach) / kWaterCell)));
    x_lo = std::fmin(x_lo, std::fmin(a.x, c.x) - half); x_hi = std::fmax(x_hi, std::fmax(a.x, c.x) + half);
    y_lo = std::fmin(y_lo, std::fmin(a.y, c.y) - half); y_hi = std::fmax(y_hi, std::fmax(a.y, c.y) + half);
    for (i32 i = i0; i <= i1; converted::pre_inc(i))
      for (i32 j = j0; j <= j1; converted::pre_inc(j)) {
        const f32 x = (static_cast<f32>(i) + 0.5f) * kWaterCell, y = (static_cast<f32>(j) + 0.5f) * kWaterCell;
        const f32 t = clampf((x - a.x) * u.x + (y - a.y) * u.y, 0, l);
        const f32 d = std::hypot(x - a.x - u.x * t, y - a.y - u.y * t);
        if (d <= half) set_water_cell(i, j);
        if (d < reach) {
          auto it = water_.find(terrain_cpp_local::key2(i >> 4, j >> 4));
          if (it == water_.end()) continue;
          WaterBlock& b = it->second;
          if (b.flow.empty()) { b.flow.assign(converted::count(256), Vec2{}); b.speed.assign(converted::count(256), 0.0f); }
          const u32 idx = static_cast<u32>(converted::plus(converted::times((j & 15), 16), (i & 15)));
          const f32 sp = speed * (1 - d / reach);
          if (converted::at(b.speed, idx) < sp) { converted::at(b.flow, idx) = u; converted::at(b.speed, idx) = sp; }
        }
      }
  }
  if (x_lo < x_hi) dirty(x_lo, y_lo, x_hi, y_hi);
}
void Terrain::add_bridge(Vec2 a, Vec2 b, f32 width) {
  const f32 l = std::hypot(b.x - a.x, b.y - a.y);
  if (l < 0.5f) return;
  // world_water.mjs: deck = the segment +1 m long, +1.5 m each side
  bridges_.push_back({(a + b) * 0.5f, l / 2 + 1, width / 2 + 1.5f, std::atan2(b.y - a.y, b.x - a.x)});
  const f32 r = l / 2 + width;
  dirty((a.x + b.x) / 2 - r, (a.y + b.y) / 2 - r, (a.x + b.x) / 2 + r, (a.y + b.y) / 2 + r);
}
