    case AreaKind::water: return ::converted_SpawnCity__main_cpp::hex_color(0x2f5f86);
    case AreaKind::park: return ::converted_SpawnCity__main_cpp::hex_color(0x4f6e35);
    case AreaKind::wood: return ::converted_SpawnCity__main_cpp::hex_color(0x3a5729);
    case AreaKind::grass: return ::converted_SpawnCity__main_cpp::hex_color(0x5a7a3c);
    case AreaKind::sand: return ::converted_SpawnCity__main_cpp::hex_color(0xc9b88f);
    case AreaKind::pitch: return ::converted_SpawnCity__main_cpp::hex_color(0x4f7a35);
