namespace city_stream_cpp_local { u64 cell_of(Vec2 c) { return cell_key(static_cast<i32>(converted::fits<int>(std::floor(c.x / kChunk))), static_cast<i32>(converted::fits<int>(std::floor(c.y / kChunk)))); } }
void CityStream::go_offline() {
  if (offline_) return;
  offline_ = true;
  for (auto& [k, t] : tiles_) remove(*converted::present(t));
  tiles_.clear();
  requests_.clear();
  lanes_.clear();
  // No map service: no elevation service either (flat ground, the stand-in town's lake).
  terrain_.clear();
  terrain_.disable_dem();
  auto t = std::make_unique<Tile>();
  converted::present(t)->procedural = true;
  converted::present(t)->key = TileKey{0, -1, -1};
  converted::present(t)->bounds = {-1e9f, -1e9f, 1e9f, 1e9f};  // the stand-in town has no square: it is everywhere
  if (training_offline) training_level(converted::present(t)->features);  // training_test_level_v2.mjs
  else procedural_city(0, 0, 760, 20261029, converted::present(t)->features);
  furnish(converted::present(t)->features, converted::present(t)->bounds, {});
  feed_terrain(*converted::present(t));
  converted::present(t)->state = Tile::State::building;
  finish_features(*converted::present(t));
  tiles_[converted::present(t)->key.hash()] = std::move(t);
}
void CityStream::feed_terrain(Tile& t) {
  // world_water.mjs: lakes / harbours (polygons) and waterways (lines with a width per class)
  // become basins in the terrain; bridges keep a solid road over them.
  for (const MapFeatures::Area& a : t.features.areas)
    if (a.kind == AreaKind::water) terrain_.add_water_polygon(a.rings);
    else terrain_.add_tint(t.key.hash(), a.rings, city_stream_cpp_local::area_color(a.kind));  // world_ground.mjs setAreas
  for (const MapFeatures::Road& r : t.features.roads) {
    if (road_is_water(r.cls)) terrain_.add_waterway(r.points, road_width(r.cls), r.cls == RoadClass::river ? 1.6f : r.cls == RoadClass::canal ? 0.5f : 1.1f);
    else if (r.bridge)
      for (std::size_t i = 0; i + 1 < r.points.size(); converted::pre_inc(i)) terrain_.add_bridge(converted::at(r.points, i), converted::at(r.points, i + 1), road_width(r.cls));
  }
}
void CityStream::finish_features(Tile& t) {
  // The streets' corridors first (terrain_craters.mjs setRoadCorridors: every street but paths
  // and tracks, its width + 3.4 m of pavements): the ground of this tile is final with them, and
  // the houses, the streets and everything else are put on it.
  {
    std::vector<f32> widths(converted::count(t.features.roads.size()));
    for (std::size_t i = 0; i < widths.size(); converted::pre_inc(i)) {
      const MapFeatures::Road& r = converted::at(t.features.roads, i);
      if (!road_is_water(r.cls) && r.cls != RoadClass::path && r.cls != RoadClass::track) converted::at(widths, i) = road_width(r.cls) + 3.4f;
    }
    terrain_.set_corridors(t.key.hash(), t.bounds, t.features.roads, widths);
  }
  // Footprint and road streams for the engine's builders, lanes for the traffic.
  t.cent.clear();
  for (MapFeatures::Building& b : t.features.buildings) {
    // terrain_craters.mjs buildingGroundBase: a house stands on the lowest ground of its outline.
    if (!b.rings.empty()) {
      const f32 g = terrain_.footprint_base(converted::at(b.rings, 0));
      b.base += g;
      b.top += g;
    }
    b.full_top = b.top;
    // destruction outlives the tile: a building that was hit stays as it was left
    if (auto d = damage_.find(b.seed); d != damage_.end()) {
      b.top = std::fmin(b.top, b.base + d->second.height);
      b.leveled = d->second.leveled;
    }
    Vec2 c{};
    if (!b.rings.empty() && !converted::at(b.rings, 0).empty()) { for (Vec2 q : converted::at(b.rings, 0)) c = c + q; c = c * (1.0f / static_cast<f32>(converted::at(b.rings, 0).size())); }
    t.cent.push_back(c);
  }
  t.prepared = true;
  ++furniture_serial_;
  for (const MapFeatures::Road& r : t.features.roads) {
    const f32 w = road_width(r.cls);
    const bool water = road_is_water(r.cls);
    if (water) continue;  // drawn by the terrain's water surface
    const bool major = static_cast<u8>(r.cls) <= static_cast<u8>(RoadClass::tertiary);
    const u32 color = water ? city_stream_cpp_local::kWater : r.cls == RoadClass::pedestrian ? city_stream_cpp_local::kPaving
                      : (r.cls == RoadClass::path || r.cls == RoadClass::track) ? city_stream_cpp_local::kPath
                      : major ? city_stream_cpp_local::kAsphaltMajor : city_stream_cpp_local::kAsphalt;
    t.roads.road(r.points.data(), static_cast<u32>(r.points.size()), w, !water && road_drivable(r.cls), color, major && !water ? static_cast<i32>(city_stream_cpp_local::kLine) : -1);
    if (!road_drivable(r.cls)) continue;
    // The lane: the street as far as it lies in this tile's own square. (A vector tile repeats
    // its streets 26 m into the neighbours: there the ground is the neighbour's - final only with
    // its own streets' corridors - and so is the lane. Clipped, the lanes of two tiles meet end to
    // end on the edge: traffic drives on across it, and nobody drives where the ground may yet change.)
    if (t.procedural) { lanes_.push_back(Lane{r.points, w, t.key.hash(), true}); continue; }
    for (std::vector<Vec2>& part : clip_line(r.points, t.bounds)) {
      f32 len = 0;
      for (std::size_t k = 0; k + 1 < part.size(); converted::pre_inc(k)) len += std::hypot(converted::at(part, k + 1).x - converted::at(part, k).x, converted::at(part, k + 1).y - converted::at(part, k).y);
      if (len > 0.5f) lanes_.push_back(Lane{std::move(part), w, t.key.hash(), true});
    }
  }
  // the buildings by cell; the cells round the view are extruded from now on (select_cells), the
  // streets are laid at once
  t.cell_items.clear();
  for (u32 i = 0; i < t.cent.size(); ++i) t.cell_items[city_stream_cpp_local::cell_of(converted::at(t.cent, i))].push_back(i);
  select_cells(focus_, true);
  begin_roads(t);
}
void CityStream::select_cells(Vec3 focus, bool force) {
  // The drawn city (world_city_buildings.mjs: the nearest MAX_FOOTPRINTS buildings within
  // VISUAL_RADIUS_M 900 m), by cell: the cells within the radius of the way ahead - from the
  // player to where he will be in a few seconds (`view_lead`) - nearest first, up to the budget of
  // buildings. A cell that is wanted is built once and kept; it goes when it lies well outside
  // the radius. So driving on only adds the cells that come into view ahead - the houses already
  // standing are never built again, and nothing is missing where the player arrives.
  const f64 now = ::converted_SpawnCity__main_cpp::now_ms();
  const Vec2 ahead{focus.x + view_lead.x, focus.y + view_lead.y};
  if (!force && std::hypot(focus.x - vis_at_.x, focus.y - vis_at_.y) < 40 && std::hypot(ahead.x - vis_ahead_.x, ahead.y - vis_ahead_.y) < 60 && now - vis_ms_ < 1000) return;
  vis_at_ = {focus.x, focus.y};
  vis_ahead_ = ahead;
  vis_ms_ = now;
  constexpr f32 kR = 900, kKeep = 220;
  const Vec2 a{focus.x, focus.y}, ab = ahead - a;
  const f32 ab2 = ab.x * ab.x + ab.y * ab.y;
  auto way_distance = [&](Vec2 p) {
    const f32 t = ab2 > 1 ? clampf(((p.x - a.x) * ab.x + (p.y - a.y) * ab.y) / ab2, 0, 1) : 0;
    return std::hypot(p.x - a.x - ab.x * t, p.y - a.y - ab.y * t);
  };
  struct Pick { f32 d; u32 tile; u64 cell; u32 n; };  // (tile: its place among tiles_)
  std::vector<Pick> picks;
  for (auto it = tiles_.begin(); it != tiles_.end(); ++it) {
    const Tile& t = *converted::present(it->second);
    if (!t.prepared) continue;
    for (const auto& [cell, items] : t.cell_items) {
      const i32 cx = static_cast<i32>(static_cast<u32>(cell >> 32)), cy = static_cast<i32>(static_cast<u32>(cell));
      const f32 d = way_distance({(static_cast<f32>(cx) + 0.5f) * city_stream_cpp_local::kChunk, (static_cast<f32>(cy) + 0.5f) * city_stream_cpp_local::kChunk});
      if (d <= kR + kKeep) picks.push_back({d, static_cast<u32>(it - tiles_.begin()), cell, static_cast<u32>(items.size())});
    }
  }
  std::stable_sort(picks.begin(), picks.end(), [](const Pick& x, const Pick& y) { return x.d < y.d || (x.d == y.d && x.cell < y.cell); });
  for (auto& [k, tp] : tiles_) converted::present(tp)->want_cells.clear();
  u32 total = 0;
  f32 reach = kR;
  for (const Pick& p : picks) {
    if (p.d > kR) break;
    if (total >= building_budget && p.d > 240) { reach = p.d; break; }  // (what is next to the player is always drawn)
    converted::present((tiles_.begin() + p.tile)->second)->want_cells.insert(p.cell);
    total += p.n;
  }
  auto settle = [&](Tile& t, const Pick& p) {
    const bool want = t.want_cells.count(p.cell) != 0, built = t.cell_ids.count(p.cell) != 0;
    if (want && !built) t.dirty_cells.insert(p.cell);
    if (!want && !built) t.dirty_cells.erase(p.cell);
    // a built cell stays while it is near the drawn radius (no flicker at its edge)
    if (!want && built && p.d > reach + kKeep * 0.5f && !t.cell_job && !t.cell_uploading) drop_cell(t, p.cell);
  };
  for (const Pick& p : picks) settle(*converted::present((tiles_.begin() + p.tile)->second), p);
  // cells beyond every radius (the player was put somewhere else): gone
  for (auto& [k, tp] : tiles_) {
    Tile& t = *converted::present(tp);
    if (t.cell_job || t.cell_uploading) continue;
    std::vector<u64> far;
    for (const auto& [cell, ids] : t.cell_ids) {
      if (t.want_cells.count(cell)) continue;
      const i32 cx = static_cast<i32>(static_cast<u32>(cell >> 32)), cy = static_cast<i32>(static_cast<u32>(cell));
      if (way_distance({(static_cast<f32>(cx) + 0.5f) * city_stream_cpp_local::kChunk, (static_cast<f32>(cy) + 0.5f) * city_stream_cpp_local::kChunk}) > kR + kKeep) far.push_back(cell);
    }
    for (u64 c : far) drop_cell(t, c);
  }
}
void CityStream::drop_cell(Tile& t, u64 cell) {
  auto it = t.cell_ids.find(cell);
  if (it == t.cell_ids.end()) return;
  for (u32 id : it->second) {
    r_->remove(id);
    converted::erase(t.meshes, std::remove(t.meshes.begin(), t.meshes.end(), id), t.meshes.end());
  }
  t.cell_ids.erase(it);
  t.dirty_cells.erase(cell);
}
void CityStream::begin_roads(Tile& t) {
  RoadOptions ro;
  // world_city_roads.mjs RADIUS_M 720 around the player - and along his way ahead (view_lead)
  const Vec2 mid{focus_.x + view_lead.x * 0.5f, focus_.y + view_lead.y * 0.5f};
  ro.center_x = mid.x;
  ro.center_y = mid.y;
  ro.radius = 720 + std::hypot(view_lead.x, view_lead.y) * 0.5f;
  ro.segment_length = 4;  // follows the 5 m terrain nodes
  ro.palette = city_stream_cpp_local::road_palette();
  // over a crater the ribbon is draped finely (0.9 m quads): it lies in the bowl, not over it
  ro.deformed = [this](f64 x, f64 y, f64 r) { return terrain_.deformed(static_cast<f32>(x), static_cast<f32>(y), static_cast<f32>(r)); };
  t.road_builder.begin(t.roads.data(), t.roads.size(), ro, terrain_.sampler());
  t.roads_at = mid;
  ++relays_;
  t.upload_next = 0;
  t.state = Tile::State::roads;
}
bool CityStream::building_at(Vec2 p) const {
  for (const auto& [k, tp] : tiles_) {
    const Tile& t = *converted::present(tp);
    if (t.state != Tile::State::ready) continue;
    if (p.x < t.bounds.x - 200 || p.x > t.bounds.z + 200 || p.y < t.bounds.y - 200 || p.y > t.bounds.w + 200) continue;
    for (const MapFeatures::Building& b : t.features.buildings) {
      if (b.rings.empty() || converted::at(b.rings, 0).size() < 3) continue;
      const std::vector<Vec2>& ring = converted::at(b.rings, 0);
      if (std::fabs(converted::at(ring, 0).x - p.x) > 150 || std::fabs(converted::at(ring, 0).y - p.y) > 150) continue;
      bool inside = false;
      for (std::size_t i = 0, j = ring.size() - 1; i < ring.size(); j = converted::post_inc(i))
        if ((converted::at(ring, i).y > p.y) != (converted::at(ring, j).y > p.y) && p.x < (converted::at(ring, j).x - converted::at(ring, i).x) * (p.y - converted::at(ring, i).y) / (converted::at(ring, j).y - converted::at(ring, i).y) + converted::at(ring, i).x) inside = !inside;
      if (!inside) continue;
      return true;
    }
  }
  return false;
}
namespace terrain_cpp_local { constexpr i32 kCells = 32; }
namespace terrain_cpp_local { constexpr f32 kWaterBlock = 64; }
namespace terrain_cpp_local { u64 key3(i32 level, i32 i, i32 j) {
  return (static_cast<u64>(level) << 56) | ((static_cast<u64>(static_cast<u32>(i)) & 0xFFFFFFF) << 28) | (static_cast<u64>(static_cast<u32>(j)) & 0xFFFFFFF);
} }
namespace terrain_cpp_local { f32 rect_distance(f32 x, f32 y, f32 x0, f32 y0, f32 x1, f32 y1) {
  const f32 dx = std::fmax(0.0f, std::fmax(x0 - x, x - x1)), dy = std::fmax(0.0f, std::fmax(y0 - y, y - y1));
  return std::sqrt(dx * dx + dy * dy);
} }
namespace terrain_cpp_local { struct WantedTile { f32 d; u64 k; }; }
void Terrain::want_tiles(Vec3 focus, Vec3 anchor) { using terrain_cpp_local::WantedTile;
  std::vector<WantedTile> render, coll, water;
  // Render: 640 m blocks out to 3.2 km; blocks near the focus split into 160 m tiles (5 m nodes
  // near, 20 m further out).
  const i32 bi = static_cast<i32>(converted::fits<int>(std::floor(focus.x / terrain_cpp_local::kBlock))), bj = static_cast<i32>(converted::fits<int>(std::floor(focus.y / terrain_cpp_local::kBlock)));
  for (i32 j = converted::minus(bj, 5); j <= converted::plus(bj, 5); converted::pre_inc(j))
    for (i32 i = converted::minus(bi, 5); i <= converted::plus(bi, 5); converted::pre_inc(i)) {
      const f32 d = terrain_cpp_local::rect_distance(focus.x, focus.y, i * terrain_cpp_local::kBlock, j * terrain_cpp_local::kBlock, (converted::plus(i, 1)) * terrain_cpp_local::kBlock, (converted::plus(j, 1)) * terrain_cpp_local::kBlock);
      if (d > 3200) continue;
      if (d < 200) {
        for (i32 b = 0; b < 4; converted::pre_inc(b))
          for (i32 a = 0; a < 4; converted::pre_inc(a)) {
            const i32 ti = converted::plus(converted::times(i, 4), a), tj = converted::plus(converted::times(j, 4), b);
            const f32 td = terrain_cpp_local::rect_distance(focus.x, focus.y, ti * terrain_cpp_local::kTile, tj * terrain_cpp_local::kTile, (converted::plus(ti, 1)) * terrain_cpp_local::kTile, (converted::plus(tj, 1)) * terrain_cpp_local::kTile);
            render.push_back({td, terrain_cpp_local::key3(td < 260 ? 0 : 1, ti, tj)});
          }
      } else {
        render.push_back({d, terrain_cpp_local::key3(2, i, j)});
      }
    }
  // Collision: 160 m tiles within 420 m of the focus (traffic lives there) and 200 m of the
  // anchor (the pilot on foot while his drone is away).
  std::vector<std::pair<Vec3, f32>> around{{focus, 420.0f}, {anchor, 200.0f}};
  for (const Vec3& m : extra) around.push_back({m, 300.0f});  // the mates (MP host): his traffic there
  for (const auto& [p, reach] : around) {
    const i32 ci = static_cast<i32>(converted::fits<int>(std::floor(p.x / terrain_cpp_local::kTile))), cj = static_cast<i32>(converted::fits<int>(std::floor(p.y / terrain_cpp_local::kTile)));
    const i32 rr = static_cast<i32>(converted::fits<int>(std::ceil(reach / terrain_cpp_local::kTile)));
    for (i32 j = converted::minus(cj, rr); j <= converted::plus(cj, rr); converted::pre_inc(j))
      for (i32 i = converted::minus(ci, rr); i <= converted::plus(ci, rr); converted::pre_inc(i)) {
        const f32 d = terrain_cpp_local::rect_distance(p.x, p.y, i * terrain_cpp_local::kTile, j * terrain_cpp_local::kTile, (converted::plus(i, 1)) * terrain_cpp_local::kTile, (converted::plus(j, 1)) * terrain_cpp_local::kTile);
        if (d <= reach) coll.push_back({d, terrain_cpp_local::key2(i, j)});
      }
  }
  // Water: 320 m chunks holding water within 2.4 km.
  kern::Set<u64> chunks;
  for (const auto& [k, b] : water_) {
    (void)b;
    const i32 bx = static_cast<i32>(k >> 32), by = static_cast<i32>(k & 0xffffffffu);
    const i32 ci = static_cast<i32>(converted::fits<int>(std::floor(bx * terrain_cpp_local::kWaterBlock / terrain_cpp_local::kWaterChunk))), cj = static_cast<i32>(converted::fits<int>(std::floor(by * terrain_cpp_local::kWaterBlock / terrain_cpp_local::kWaterChunk)));
    chunks.insert(terrain_cpp_local::key2(ci, cj));
  }
  for (u64 k : chunks) {
    const i32 i = static_cast<i32>(k >> 32), j = static_cast<i32>(k & 0xffffffffu);
    const f32 d = terrain_cpp_local::rect_distance(focus.x, focus.y, i * terrain_cpp_local::kWaterChunk, j * terrain_cpp_local::kWaterChunk, (converted::plus(i, 1)) * terrain_cpp_local::kWaterChunk, (converted::plus(j, 1)) * terrain_cpp_local::kWaterChunk);
    if (d < 2400) water.push_back({d, k});
  }
  auto finish = [](std::vector<WantedTile>& v, std::vector<u64>& out) {
    std::stable_sort(v.begin(), v.end(), [](const WantedTile& a, const WantedTile& b) { return a.d < b.d; });
    out.clear();
    for (const WantedTile& w : v)
      if (std::find(out.begin(), out.end(), w.k) == out.end()) out.push_back(w.k);
  };
  finish(render, want_render_);
  finish(coll, want_collision_);
  finish(water, want_water_);
  planned_focus_ = focus;
  planned_anchor_ = anchor;
  planned_extra_ = extra;
  replan_ = false;
}
void Terrain::build_collision_tile(i32 ti, i32 tj) {
  // terrain_tiles.mjs: 32 cells of 5 m plus one cell into each neighbour with the outer ring sunk,
  // so the seam is an interior edge of both tiles (no ghost contacts on fast wheels).
  const i32 N = converted::plus(terrain_cpp_local::kCells, 3);
  const f32 x0 = ti * terrain_cpp_local::kTile - kStep, y0 = tj * terrain_cpp_local::kTile - kStep;
  std::vector<Vec3> pts(converted::count(static_cast<std::size_t>(N) * N));
  for (i32 r = 0; r < N; converted::pre_inc(r))
    for (i32 c = 0; c < N; converted::pre_inc(c)) {
      const f32 x = x0 + c * kStep, y = y0 + r * kStep;
      f32 z = node_height(x, y);
      if (r == 0 || c == 0 || r == converted::minus(N, 1) || c == converted::minus(N, 1)) z -= kSkirtDrop;
      converted::at(pts, static_cast<std::size_t>(r) * N + c) = {x, y, z};
    }
  std::vector<u32> idx;
  idx.reserve(converted::count(static_cast<std::size_t>(converted::minus(N, 1)) * (converted::minus(N, 1)) * 6));
  for (i32 r = 0; converted::plus(r, 1) < N; converted::pre_inc(r))
    for (i32 c = 0; converted::plus(c, 1) < N; converted::pre_inc(c)) {
      const u32 a = static_cast<u32>(converted::plus(converted::times(r, N), c)), b = a + 1, cc = a + static_cast<u32>(N), d = cc + 1;
      idx.insert(idx.end(), {a, b, d, a, d, cc});
    }
  // the same ground as the tile already has (a street laid again, a change beside it): nothing is written - the
  // physics world sees a change of the ground only when there is one
  CollisionTile& t = collision_[terrain_cpp_local::key2(ti, tj)];
  if (t.body.valid() && world_->body_valid(t.body) && t.pts.size() == pts.size()) {
    bool same = true;
    for (std::size_t q = 0; q < pts.size() && same; converted::pre_inc(q)) same = converted::at(t.pts, q).x == converted::at(pts, q).x && converted::at(t.pts, q).y == converted::at(pts, q).y && converted::at(t.pts, q).z == converted::at(pts, q).z;
    if (same) return;
  }
  physics::BodySettings bs;
  bs.type = physics::BodyType::fixed;
  const physics::Body body = world_->create_body(bs);
  physics::ShapeSettings ss;
  ss.kind = physics::ShapeKind::mesh;
  ss.points = Span<const Vec3>(pts.data(), pts.size());
  ss.indices = Span<const u32>(idx.data(), idx.size());
  ss.material.friction = 0.8f;  // the level's ground friction so far
  ss.material.category_bits = kCatWorld;
  world_->create_shape(body, ss);
  // New field first, then the old one goes (terrain_tiles.mjs writeTile order).
  if (t.body.valid() && world_->body_valid(t.body)) world_->destroy_body(t.body);
  t.body = body;
  t.pts = std::move(pts);
}
void Terrain::collide(Vec3 focus, Vec3 anchor, u32 more) {
  if (!world_ || !settled_) return;
  bool extra_moved = extra.size() != planned_extra_.size();
  for (std::size_t i = 0; !extra_moved && i < extra.size(); converted::pre_inc(i)) extra_moved = std::hypot(converted::at(extra, i).x - converted::at(planned_extra_, i).x, converted::at(extra, i).y - converted::at(planned_extra_, i).y) > 40;
  if (replan_ || extra_moved || std::hypot(focus.x - planned_focus_.x, focus.y - planned_focus_.y) > 40 ||
      std::hypot(anchor.x - planned_anchor_.x, anchor.y - planned_anchor_.y) > 40)
    want_tiles(focus, anchor);
  // the ground right under the focus and the anchor (and their neighbours) before the step, whatever it costs: a
  // jet at 250 m/s or a reload of the elevation never leaves a hole under anybody
  std::vector<Vec3> under{focus, anchor};
  under.insert(under.end(), extra.begin(), extra.end());
  for (const Vec3& at : under) {
    const i32 ci = static_cast<i32>(converted::fits<int>(std::floor(at.x / terrain_cpp_local::kTile))), cj = static_cast<i32>(converted::fits<int>(std::floor(at.y / terrain_cpp_local::kTile)));
    for (i32 j = converted::minus(cj, 1); j <= converted::plus(cj, 1); converted::pre_inc(j))
      for (i32 i = converted::minus(ci, 1); i <= converted::plus(ci, 1); converted::pre_inc(i)) {
        const u64 k = terrain_cpp_local::key2(i, j);
        if (collision_.count(k) && !dirty_collision_.count(k)) continue;
        build_collision_tile(i, j);
        dirty_collision_.erase(k);
        ++stats_.rebuilds;
      }
  }
  // the other wanted tiles (what stands on them must not fall): `more` in this step, the nearest first
  bool missing = false;
  u32 built = 0;
  for (u64 k : want_collision_) {
    if (collision_.count(k) && !dirty_collision_.count(k)) continue;
    if (built >= more) { missing = true; break; }
    build_collision_tile(static_cast<i32>(k >> 32), static_cast<i32>(k & 0xffffffffu));
    dirty_collision_.erase(k);
    ++stats_.rebuilds;
    ++built;
  }
  if (!missing && collision_.size() > want_collision_.size()) {
    // every wanted tile stands: what is no longer wanted goes (never before - no holes)
    const kern::Set<u64> keep(want_collision_.begin(), want_collision_.end());
    for (auto it = collision_.begin(); it != collision_.end();) {
      if (!keep.count(it->first)) {
        if (it->second.body.valid() && world_->body_valid(it->second.body)) world_->destroy_body(it->second.body);
        dirty_collision_.erase(it->first);
        it = collision_.erase(it);
      } else ++it;
    }
  }
  stats_.collision_tiles = static_cast<u32>(collision_.size());
}
namespace city_stream_cpp_local { f64 signed_area(const std::vector<Vec2>& r) {
  f64 a = 0;
  for (std::size_t i = 0, j = r.size() - 1; i < r.size(); j = converted::post_inc(i)) a += static_cast<f64>(converted::at(r, j).x) * converted::at(r, i).y - static_cast<f64>(converted::at(r, i).x) * converted::at(r, j).y;
  return a * 0.5;
} }
void CityStream::collide(Vec3 focus, bool whole) {
  if (!world_) return;
  terrain_.collide(focus, anchor, whole ? 1000000u : 1u);
  if (near_.steps < kNearSteps) ++near_.steps;
  update_collision(focus, whole);
  stats_.colliders = near_.colliders;
  stats_.t_collision = ms_.t_collision;
}
void CityStream::update_collision(Vec3 focus, bool whole) {
  NearCollision& n = near_;
  // (along the way ahead - view_lead: a fast car has its walls before it gets there)
  const Vec2 way_a{focus.x, focus.y}, way_ab{view_lead.x, view_lead.y};
  const f32 way_l2 = way_ab.x * way_ab.x + way_ab.y * way_ab.y;
  auto way_d2 = [&](Vec2 p) {
    const f32 t = way_l2 > 1 ? clampf(((p.x - way_a.x) * way_ab.x + (p.y - way_a.y) * way_ab.y) / way_l2, 0, 1) : 0;
    const f32 dx = p.x - way_a.x - way_ab.x * t, dy = p.y - way_a.y - way_ab.y * t;
    return dx * dx + dy * dy;
  };
  bool moved = std::hypot(focus.x - n.at.x, focus.y - n.at.y) >= 140 || std::hypot(focus.x + view_lead.x - n.ahead.x, focus.y + view_lead.y - n.ahead.y) >= 140 ||
               extra_foci.size() != n.mates_at.size();
  for (std::size_t i = 0; !moved && i < extra_foci.size(); converted::pre_inc(i)) moved = std::hypot(converted::at(extra_foci, i).x - converted::at(n.mates_at, i).x, converted::at(extra_foci, i).y - converted::at(n.mates_at, i).y) >= 140;
  if (!n.building && (moved || (n.dirty && n.steps >= kNearSteps))) {
    // world_building_collisions.mjs: the nearest MAX_FOOTPRINTS 480 within RADIUS_M 340
    struct Pick { f32 d2; u64 tile; u32 i; };
    std::vector<Pick> all;
    for (auto& [k, tp] : tiles_) {
      const Tile& t = *converted::present(tp);
      if (t.state != Tile::State::ready && t.state != Tile::State::building && t.state != Tile::State::roads && t.state != Tile::State::areas) continue;
      if (!t.prepared) continue;
      for (u32 i = 0; i < t.cent.size(); ++i) {
        if (k == excl_tile_ && static_cast<i32>(i) == excl_index_) continue;  // an entered interior (M3 life)
        f32 d2 = way_d2(converted::at(t.cent, i));
        // (MP host: the buildings around the mates too - his traffic and people there collide)
        for (const Vec3& m : extra_foci) { const f32 mx = converted::at(t.cent, i).x - m.x, my = converted::at(t.cent, i).y - m.y; d2 = std::fmin(d2, mx * mx + my * my); }
        if (d2 <= 340.0f * 340.0f) all.push_back({d2, k, i});
      }
    }
    std::stable_sort(all.begin(), all.end(), [](const Pick& a, const Pick& b) { return a.d2 < b.d2; });
    const std::size_t cap = 480 + 320 * extra_foci.size();
    if (all.size() > cap) all.resize(converted::count(cap));
    n.list.clear();
    for (const Pick& p : all) n.list.push_back({p.tile, p.i});
    n.old_body = n.body;
    n.body = {};
    n.next = 0;
    n.colliders = 0;
    n.building = true;
    n.dirty = false;
    n.at = {focus.x, focus.y};
    n.ahead = {focus.x + view_lead.x, focus.y + view_lead.y};
    n.mates_at = extra_foci;
    n.steps = 0;
  }
  if (n.building && build_near(whole)) {
    if (n.old_body.valid() && world_->body_valid(n.old_body)) world_->destroy_body(n.old_body);
    n.old_body = {};
    n.building = false;
    n.built = true;
    if (ms_.t_collision < 0 && !n.list.empty()) ms_.t_collision = ::converted_SpawnCity__main_cpp::now_ms() - start_ms_;
  }
}
bool CityStream::build_near(bool whole) {
  NearCollision& n = near_;
  u32 built = 0;
  if (!n.body.valid()) {
    physics::BodySettings bs;
    bs.type = physics::BodyType::fixed;
    n.body = world_->create_body(bs);
    n.shapes.assign(converted::count(n.list.size()), {});
  }
  while (n.next < n.list.size()) {
    const std::size_t slot = converted::post_inc(n.next);
    const auto [tile_key, bi] = converted::at(n.list, slot);
    auto it = tiles_.find(tile_key);
    if (it == tiles_.end() || bi >= converted::present(it->second)->features.buildings.size()) continue;
    converted::at(n.shapes, slot) = building_shape(n.body, converted::at(converted::present(it->second)->features.buildings, bi));
    if (converted::at(n.shapes, slot).valid()) ++n.colliders;
    if (!whole && ++built >= kNearPerStep) return n.next >= n.list.size();
  }
  return true;
}
physics::Shape CityStream::building_shape(physics::Body body, const MapFeatures::Building& b) {
  Earcut earcut;
  std::vector<f64> xy;
  std::vector<u32> holes, tris, idx;
  std::vector<Vec3> pts;
  xy.clear(); holes.clear(); tris.clear(); idx.clear(); pts.clear();
  std::vector<std::vector<Vec2>> rings = b.rings;
  // MAX_VERTICES 64 per ring
  for (auto& ring : rings)
    if (ring.size() > 64) { const std::size_t step = (ring.size() + 63) / 64; std::vector<Vec2> thin; for (std::size_t k = 0; k < ring.size(); k += step) thin.push_back(converted::at(ring, k)); ring = std::move(thin); }
  for (std::size_t r = 0; r < rings.size(); converted::pre_inc(r)) {
    auto& ring = converted::at(rings, r);
    if (ring.size() < 3) continue;
    const f64 a = city_stream_cpp_local::signed_area(ring);
    if (std::fabs(a) < 0.5) continue;
    if ((r == 0) != (a > 0)) std::reverse(ring.begin(), ring.end());  // outer CCW, courtyards CW
    if (r) holes.push_back(static_cast<u32>(xy.size() / 2));
    for (Vec2 p : ring) xy.insert(xy.end(), {p.x, p.y});
    // Walls: quads per edge, outward = right of the edge for CCW outer / CW holes.
    for (std::size_t i = 0; i < ring.size(); converted::pre_inc(i)) {
      const Vec2 p0 = converted::at(ring, i), p1 = converted::at(ring, converted::rem((i + 1), ring.size()));
      const u32 base = static_cast<u32>(pts.size());
      pts.push_back({p0.x, p0.y, b.base});
      pts.push_back({p1.x, p1.y, b.base});
      pts.push_back({p1.x, p1.y, b.top});
      pts.push_back({p0.x, p0.y, b.top});
      idx.insert(idx.end(), {base, base + 1, base + 2, base, base + 2, base + 3});
    }
  }
  if (xy.size() >= 6) {
    earcut.triangulate(xy.data(), static_cast<u32>(xy.size() / 2), holes.data(), static_cast<u32>(holes.size()), tris);
    const u32 base = static_cast<u32>(pts.size());
    for (std::size_t i = 0; i < xy.size() / 2; converted::pre_inc(i)) pts.push_back({static_cast<f32>(converted::at(xy, i * 2)), static_cast<f32>(converted::at(xy, i * 2 + 1)), b.top});
    for (std::size_t i = 0; i + 2 < tris.size(); i += 3) {
      u32 a = base + converted::at(tris, i), c = base + converted::at(tris, i + 1), d = base + converted::at(tris, i + 2);
      if (::converted_SpawnCity__main_cpp::cross(converted::at(pts, c) - converted::at(pts, a), converted::at(pts, d) - converted::at(pts, a)).z < 0) std::swap(c, d);
      idx.insert(idx.end(), {a, c, d});
    }
  }
  if (!idx.empty()) {
    physics::ShapeSettings ss;
    ss.kind = physics::ShapeKind::mesh;
    ss.points = Span<const Vec3>(pts.data(), pts.size());
    ss.indices = Span<const u32>(idx.data(), idx.size());
    ss.material.friction = 0.7f;
    ss.material.category_bits = kCatWorld;
    return world_->create_shape(body, ss);
  }
  return {};
}
