bool SpawnCity::place() {
  Vec3 at{0, 0, 0};
  bool found = false;
  for (i32 ring = 0; ring < 40 && !found; converted::pre_inc(ring)) {
    const i32 n = ring == 0 ? 1 : converted::times(ring, 8);
    for (i32 k = 0; k < n && !found; converted::pre_inc(k)) {
      const f32 a = static_cast<f32>(k) * 2 * kPi / static_cast<f32>(n), r = static_cast<f32>(ring) * 5;
      const Vec2 p{r * std::cos(a), r * std::sin(a)};
      if (!city_.building_at(p)) { at = {p.x, p.y, 0}; found = true; }
    }
  }
  // the collision round the start, all of it, before the first step (CityStream::collide)
  city_.collide(at, true);
  const f32 ground = city_.ground_height(at.x, at.y);
  const RayResult g = cast(converted::present(world_)->physics(), {at.x, at.y, ground + 60}, {0, 0, -1}, 80, converted::present(world_)->actor_body(drone_actor_));
  at.z = (g.hit ? g.point.z : ground) + 0.0225f;
  converted::present(world_)->set_alive(drone_actor_, true);
  const Vec3 rot{0, 0, 180};  // the nose (-X) looks along +X
  converted::present(world_)->teleport(drone_actor_, at, &rot);
  converted::present(world_)->set_actor_velocity(drone_actor_, {});
  drone_.reset();
  sticks_ = DroneSticks{};
  sticks_.clearance = settings_.get(Opt::drone_hover_agl);
  landing_ = false;
  height_held_ = false;
  accumulator_ = 0;
  rig_init_ = false;
  focus_prev_valid_ = false;
  placed_ = true;
  converted::present(world_)->set_paused(false);
  engine_->set_status("");
  toast_ = city_.offline() ? "" : "Willkommen in SpawnCity";
  toast_age_ = city_.offline() ? 99 : 0;
  return true;
}
void SpawnCity::reset() {
  if (!placed_) return;
  place();
  ++resets_;
  toast_ = "Zurueck zum Start";
  toast_age_ = 0;
}
void SpawnCity::move_world(f64 lon, f64 lat) {
  lon_ = lon;
  lat_ = lat;
  city_.clear();
  city_.start(engine_->renderer(), converted::present(world_)->physics(), lon_, lat_, engine_->arg_number("dem", 1) > 0 && engine_->arg_number("offline", 0) <= 0);
  if (engine_->arg_number("offline", 0) > 0) city_.go_offline();
  converted::present(world_)->set_alive(drone_actor_, false);
  converted::present(world_)->set_paused(true);
  placed_ = false;
  ++moves_;
  toast_ = "Neuer Startort - die Stadt wird geladen";
  toast_age_ = 0;
}
