  std::snprintf(b, sizeof b, ",\"drone\":{\"armed\":%s,\"calibrating\":%s,\"fault\":%s,\"game\":%s,\"landing\":%s,\"battery\":%.2f,\"volts\":%.2f,\"amps\":%.1f,\"clearance\":%.1f,"
                "\"cam\":%d,\"pulses\":[%u,%u,%u,%u]}",
                t.armed ? "true" : "false", t.calibrating ? "true" : "false", t.fault ? "true" : "false", sticks_.game_mode ? "true" : "false", landing_ ? "true" : "false",
                static_cast<double>(t.battery_soc), static_cast<double>(t.battery_v), static_cast<double>(t.current_a), static_cast<double>(sticks_.clearance), cam_mode_, t.pulses[0], t.pulses[1], t.pulses[2], t.pulses[3]);
  s += b;
  std::snprintf(b, sizeof b, ",\"speed\":%.2f,\"vz\":%.2f,\"agl\":%.1f,\"alt\":%.1f,\"x\":%.2f,\"y\":%.2f", static_cast<double>(::converted_SpawnCity__main_cpp::length(vel)), static_cast<double>(vel.z), static_cast<double>(agl), static_cast<double>(pos.z), static_cast<double>(pos.x), static_cast<double>(pos.y));
  s += b;
  f64 lon = lon_, lat = lat_;
