  if (toast_age_ < 4) s += ",\"toast\":\"" + spiel_cpp_local::json_escape(toast_) + "\"";
  std::snprintf(b, sizeof b, ",\"ui\":{\"placed\":%s,\"paused\":%s,\"settings\":%u,\"resets\":%u,\"moves\":%u,\"origin\":[%.6f,%.6f],\"northUp\":%s,\"audioOn\":%s,\"musicOn\":%s}",
                placed_ ? "true" : "false", paused_ ? "true" : "false", settings_.version(), resets_, moves_, lat_, lon_, settings_.on(Opt::view_minimap_north) ? "true" : "false",
                settings_.on(Opt::audio_on) ? "true" : "false", settings_.on(Opt::music_on) ? "true" : "false");
  s += b;
  std::snprintf(b, sizeof b, ",\"ctl\":{\"device\":\"%s\",\"pad\":%s,\"locked\":%s,\"fingers\":%s,\"hint\":\"%s\",\"sticks\":[%.3f,%.3f,%.3f,%.3f],\"view\":{\"eye\":[%.2f,%.2f,%.2f]}}",
                touch_mode_ ? "touch" : "desktop", pad.connected ? "true" : "false", locked_ ? "true" : "false", touch_.any() ? "true" : "false", spiel_cpp_local::json_escape(controls::hint_line("drone", "", false)).c_str(),
                static_cast<double>(sticks_.roll), static_cast<double>(sticks_.pitch), static_cast<double>(sticks_.yaw), static_cast<double>(sticks_.body_pitch), static_cast<double>(cam_.eye.x), static_cast<double>(cam_.eye.y), static_cast<double>(cam_.eye.z));
  s += b;
